use scraper::{Html,Selector};use serde::Serialize;use serde_json::Value;use sha2::{Digest,Sha256};use url::Url;
#[derive(Debug,Serialize,Clone)]#[serde(rename_all="camelCase")]pub struct Heading{pub level:u8,pub text:String}
#[derive(Debug,Serialize,Clone)]#[serde(rename_all="camelCase")]pub struct Page{pub id:String,pub url:Url,pub status:u16,pub title:String,pub description:String,pub canonical_url:Option<Url>,pub headings:Vec<Heading>,pub text:String,pub links:Vec<Url>,pub json_ld:Vec<Value>,pub fingerprint:String,pub content_type:String,pub duplicate_of:Option<String>}
pub fn extract(url:Url,status:u16,content_type:String,html:&str)->Page{let doc=Html::parse_document(html);let one=|css:&str|Selector::parse(css).ok().and_then(|s|doc.select(&s).next()).map(|e|clean(&e.text().collect::<Vec<_>>().join(" "))).unwrap_or_default();let title=one("title");let description=Selector::parse("meta[name='description']").ok().and_then(|s|doc.select(&s).next()).and_then(|e|e.value().attr("content")).map(clean).unwrap_or_default();let canonical_url=Selector::parse("link[rel='canonical']").ok().and_then(|s|doc.select(&s).next()).and_then(|e|e.value().attr("href")).and_then(|x|url.join(x).ok());let mut headings=vec![];for level in 1..=6{if let Ok(s)=Selector::parse(&format!("h{level}")){for e in doc.select(&s){let text=clean(&e.text().collect::<Vec<_>>().join(" "));if !text.is_empty(){headings.push(Heading{level,text})}}}}let text=Selector::parse("main,article,body").ok().and_then(|s|doc.select(&s).next()).map(|e|clean(&e.text().collect::<Vec<_>>().join(" "))).unwrap_or_default();let links=Selector::parse("a[href]").unwrap();let links=doc.select(&links).filter_map(|e|e.value().attr("href")).filter_map(|x|url.join(x).ok()).filter(|x|matches!(x.scheme(),"http"|"https")).collect();let ld=Selector::parse("script[type='application/ld+json']").unwrap();let json_ld=doc.select(&ld).filter_map(|e|serde_json::from_str(&e.inner_html()).ok()).collect();let fingerprint=hex::encode(Sha256::digest(text.as_bytes()));let id=fingerprint.chars().take(12).collect();Page{id,url,status,title,description,canonical_url,headings,text,links,json_ld,fingerprint,content_type,duplicate_of:None}}
fn clean(s:&str)->String{s.split_whitespace().collect::<Vec<_>>().join(" ")}
#[cfg(test)]mod tests{use super::*;#[test]fn extracts_semantics(){let p=extract(Url::parse("https://example.com").unwrap(),200,"text/html".into(),"<title>Ada</title><meta name='description' content='AI engineer'><main><h1>Ada Example</h1><p>Created Atlas.</p></main>");assert_eq!(p.title,"Ada");assert!(p.text.contains("Atlas"));assert_eq!(p.headings.len(),1)}}
